}

const unmet = [...dispatch.blocking];
const invalid = discoveryErrors.map((error) => "discovery:PARSE " + safeHostText(error));
const handoffs = [...dispatch.abandoned];
const handoffMessage = () => {
  if (!handoffs.length) return "";
